static int deleteExpired(List<Segment> segments, long nowMs, long retentionMs) {
    int deleted = 0;
    while (!segments.isEmpty()) {
        Segment oldest = segments.get(0);
        boolean expired = !oldest.getRecords().isEmpty()
                && nowMs - oldest.getMaxTimestampMs() > retentionMs;
        if (!expired) break;          // the first young segment stops the sweep
        segments.remove(0);           // the whole file goes
        deleted++;
    }
    return deleted;
}

