fun deleteExpired(segments: MutableList<Segment>, nowMs: Long, retentionMs: Long): Int {
    var deleted = 0
    while (segments.isNotEmpty()) {
        val oldest = segments[0]
        val expired = oldest.records.isNotEmpty() && nowMs - oldest.maxTimestampMs > retentionMs
        if (!expired) break           // the first young segment stops the sweep
        segments.removeAt(0)          // the whole file goes
        deleted++
    }
    return deleted
}
